#nullable enable
var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

List<Book> books =
[
    new(1, "Hatchet", "Gary Paulsen"),
    new(2, "The Hobbit", "J. R. R. Tolkien"),
    new(3, "Dragon Rider", "Cornelia Funke"),
    new(4, "How to Train Your Dragon", "Cressida Cowell"),
    new(5, "Holes", "Louis Sachar"),
];

var group = app.MapGroup("/books");

// TODO 1: /books/abc and a missing book
// should both be 404 Not Found.
group.MapGet("/{id:int}", (int id) =>
    books.FirstOrDefault(b => b.Id == id) is { } book
        ? Results.Ok(book)
        : Results.NotFound());

// TODO 2: search is optional and ignores case.
// TODO 3: 2 books a page; ?page=2 is page 2,
// and no page means page 1.
group.MapGet("/", (string? search, int page = 1) =>
    books
        .Where(b => search is null
            || b.Title.Contains(search, StringComparison.OrdinalIgnoreCase))
        .Skip((page - 1) * 2)
        .Take(2));

app.Run();

record Book(int Id, string Title, string Author);

