public record Score(
    string Player, int Points, DateTime At);

public interface IScoreStore
{
    void Add(Score score);
    IReadOnlyList<Score> All();
}

public class InMemoryScoreStore : IScoreStore
{
    private readonly List<Score> _scores = [];
    public void Add(Score score) => _scores.Add(score);
    public IReadOnlyList<Score> All() => _scores;
}

public interface IClock
{
    DateTime Now { get; }
}

public class SystemClock : IClock
{
    public DateTime Now => DateTime.UtcNow;
}

// For tests: a clock that always says one time.
public class FixedClock(DateTime now) : IClock
{
    public DateTime Now => now;
}

// One per request: what this request has done.
public class RequestLog
{
    public int Writes { get; set; }
}

public class ScoreService(IScoreStore store, RequestLog log)
{
    // TODO 3: take an IClock in the constructor
    // instead of making a SystemClock here.
    private readonly IClock _clock = new SystemClock();

    public Score Submit(string player, int points)
    {
        var score = new Score(player, points, _clock.Now);
        store.Add(score);
        log.Writes++;
        return score;
    }

    public IEnumerable<Score> Top(int count) =>
        store.All()
            .OrderByDescending(s => s.Points)
            .ThenBy(s => s.At)
            .Take(count);
}

