var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<GuestDb>(
    o => o.UseInMemoryDatabase("guests"));
var app = builder.Build();

app.MapGet("/guests", (GuestDb db) =>
    db.Guests.OrderBy(g => g.Name).ToList());

app.MapGet("/guests/{animal}", (string animal, GuestDb db) =>
    db.Guests.Where(g => g.Animal == animal).ToList());

app.MapPost("/guests", (Guest guest, GuestDb db) =>
{
    db.Guests.Add(guest);
    db.SaveChanges();
    return Results.Created($"/guests/{guest.Id}", guest);
});

app.Run();

public class Guest
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Animal { get; set; } = "";
}

public class GuestDb(DbContextOptions<GuestDb> options)
    : DbContext(options)
{
    public DbSet<Guest> Guests => Set<Guest>();
}

