using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<TodoDb>(
    o => o.UseInMemoryDatabase("todos"));
var app = builder.Build();

// Create the database and its seed rows.
using (var scope = app.Services.CreateScope())
{
    scope.ServiceProvider.GetRequiredService<TodoDb>()
        .Database.EnsureCreated();
}

// SELECT ... WHERE Done = 0 ORDER BY Title
app.MapGet("/todos", async (TodoDb db) =>
    await db.Todos.AsNoTracking()
        .Where(t => !t.Done)
        .OrderBy(t => t.Title)
        .ToListAsync());

// A tracked change: SaveChanges sends an UPDATE.
app.MapPost("/todos/{id:int}/done", async (int id, TodoDb db) =>
{
    var todo = await db.Todos.FindAsync(id);
    if (todo is null)
    {
        return Results.NotFound();
    }
    todo.Done = true;
    await db.SaveChangesAsync();
    return Results.Ok(todo);
});

app.Run();

public class Todo
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public bool Done { get; set; }
}

public class TodoDb(DbContextOptions<TodoDb> options)
    : DbContext(options)
{
    public DbSet<Todo> Todos => Set<Todo>();

    protected override void OnModelCreating(ModelBuilder model) =>
        model.Entity<Todo>().HasData(
            new Todo { Id = 1, Title = "Water the ferns" },
            new Todo { Id = 2, Title = "Fix the gate" },
            new Todo { Id = 3, Title = "Book the hall", Done = true });
}

