using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/[controller]")]
public class ScoresController(ArcadeDb db)
    : ControllerBase
{
    // TODO 2: GET /api/scores?game=tetra: that
    // game's top 3, highest first. Let the
    // database filter, sort and limit.
    [HttpGet]
    public async Task<List<Score>> Get(string game) =>
        await db.Scores
            .Where(s => s.Game == game)
            .OrderByDescending(s => s.Points)
            .Take(3)
            .ToListAsync();

    [HttpGet("{id:int}")]
    public async Task<ActionResult<Score>> GetById(
        int id)
    {
        var score = await db.Scores.FindAsync(id);
        if (score is null)
        {
            return NotFound();
        }
        return score;
    }

    // TODO 3: this answers 201, but the score
    // is never saved.
