    public async Task<ActionResult<Score>> Create(
        NewScore input)
    {
        var score = new Score
        {
            Game = input.Game,
            Player = input.Player,
            Points = input.Points,
        };
        db.Scores.Add(score);
        await db.SaveChangesAsync();
        return CreatedAtAction(nameof(GetById),
            new { id = score.Id }, score);
    }

    // TODO 4: DELETE /api/scores/{id:int}: 204
    // if it was there, 404 if not.
    [HttpDelete("{id:int}")]
    public async Task<IActionResult> Delete(int id)
    {
        var score = await db.Scores.FindAsync(id);
        if (score is null)
        {
            return NotFound();
        }
        db.Scores.Remove(score);
        await db.SaveChangesAsync();
        return NoContent();
    }
}

