using Microsoft.EntityFrameworkCore;

// Project: the Grove Lost & Found!
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<GroveDb>(
    o => o.UseInMemoryDatabase("lost-found"));
var app = builder.Build();

// 1. POST /items: save a found thing, and
//    answer 201 Created. If it has no name,
//    answer BadRequest and don't save it.
app.MapPost("/items", (LostItem item, GroveDb db) =>
{
    if (string.IsNullOrWhiteSpace(item.Name))
    {
        return Results.BadRequest("A lost thing needs a name.");
    }
    db.Items.Add(item);
    db.SaveChanges();
    return Results.Created($"/items/{item.Id}", item);
});

// 2. GET /items: only the things nobody has
//    claimed yet.
app.MapGet("/items", (GroveDb db) =>
    db.Items.Where(i => !i.Claimed).ToList());

// 3. GET /items/{id:int}: one thing, or
//    NotFound if there's no such thing.
app.MapGet("/items/{id:int}", (int id, GroveDb db) =>
{
    var item = db.Items.Find(id);
    if (item is null)
    {
        return Results.NotFound();
    }
    return Results.Ok(item);
});

// 4. POST /items/{id:int}/claim: mark the
//    thing as claimed and save. NotFound if
//    there's no such thing.
app.MapPost("/items/{id:int}/claim", (int id, GroveDb db) =>
{
    var item = db.Items.Find(id);
    if (item is null)
    {
        return Results.NotFound();
    }
    item.Claimed = true;
    db.SaveChanges();
    return Results.Ok(item);
});

app.Run();

