using System.ComponentModel.DataAnnotations;
using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<CampDb>(
    o => o.UseInMemoryDatabase("camp"));
var app = builder.Build();

using (var scope = app.Services.CreateScope())
{
    scope.ServiceProvider.GetRequiredService<CampDb>()
        .Database.EnsureCreated();
}

// A projection: the query works out BedsLeft.
app.MapGet("/cabins", async (CampDb db) =>
    await db.Cabins
        .Select(c => new CabinSummary(
            c.Id, c.Name, c.Beds - c.Booked))
        .ToListAsync());

// Two campers book Willow's last bed at the same moment,
// each with their own DbContext (as two requests would).
app.MapPost("/race", async (IServiceScopeFactory scopes) =>
{
    using var a = scopes.CreateScope();
    using var b = scopes.CreateScope();
    var dbA = a.ServiceProvider.GetRequiredService<CampDb>();
    var dbB = b.ServiceProvider.GetRequiredService<CampDb>();
    var cabinA = await dbA.Cabins.FindAsync(2);
    var cabinB = await dbB.Cabins.FindAsync(2);
    if (cabinA.Booked >= cabinA.Beds)
    {
        return "Willow is full. Press Run to start over.";
    }
    cabinA.Booked++;   // both saw one bed left
    cabinB.Booked++;
    await dbA.SaveChangesAsync();
    try
    {
        await dbB.SaveChangesAsync();
        return "Both saved: two campers, one bed!";
    }
    catch (DbUpdateConcurrencyException)
    {
        return "Camper A got the bed. Camper B: 409, try again.";
    }
});

app.Run();

public class Cabin
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public int Beds { get; set; }

    [ConcurrencyCheck]   // try removing this
    public int Booked { get; set; }
}

public record CabinSummary(int Id, string Name, int BedsLeft);

public class CampDb(DbContextOptions<CampDb> options)
    : DbContext(options)
{
    public DbSet<Cabin> Cabins => Set<Cabin>();

    protected override void OnModelCreating(ModelBuilder model) =>
        model.Entity<Cabin>().HasData(
            new Cabin { Id = 1, Name = "Oak", Beds = 6, Booked = 2 },
            new Cabin { Id = 2, Name = "Willow", Beds = 4, Booked = 3 });
}

