using System.ComponentModel.DataAnnotations;
using Microsoft.EntityFrameworkCore;

public class Event
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public DateOnly Date { get; set; }
    public int Capacity { get; set; }

    // 5. Two buyers can both see the last seats
    //    and both save. Make this a concurrency
    //    token.
    public int TicketsSold { get; set; }
}

public class Ticket
{
    public int Id { get; set; }
    public int EventId { get; set; }
    public string Buyer { get; set; } = "";
    public int Quantity { get; set; }
}

// What a client sends to buy tickets.
public record NewTicket(
    [Required, StringLength(20)] string Buyer,
    [Range(1, 4)] int Quantity);

// What the events endpoints answer.
public record EventSummary(
    int Id, string Name, DateOnly Date,
    int SeatsLeft);

public class TicketsDb(DbContextOptions<TicketsDb> o)
    : DbContext(o)
{
    public DbSet<Event> Events => Set<Event>();
    public DbSet<Ticket> Tickets => Set<Ticket>();

    // Seed events, added by EnsureCreated.
    protected override void OnModelCreating(
        ModelBuilder model) =>
        model.Entity<Event>().HasData(
            Seed(1, "Robotics Expo", 5, 200, 120),
            Seed(2, "Indie Game Jam", 12, 50, 48),
            Seed(3, "Hack the Grove", 1, 30, 0));

    // An event in December 2026.
    private static Event Seed(int id, string name,
        int day, int capacity, int sold) =>
        new() { Id = id, Name = name,
                Date = new DateOnly(2026, 12, day),
                Capacity = capacity,
                TicketsSold = sold };
}

