using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/[controller]")]
public class EventsController(TicketsDb db)
    : ControllerBase
{
    // Finished: one event, as an EventSummary.
    [HttpGet("{id:int}")]
    public async Task<ActionResult<EventSummary>>
        GetEvent(int id)
    {
        var summary = await db.Events
            .Where(e => e.Id == id)
            .Select(e => new EventSummary(
                e.Id, e.Name, e.Date,
                e.Capacity - e.TicketsSold))
            .FirstOrDefaultAsync();
        if (summary is null)
        {
            return NotFound();
        }
        return summary;
    }

    // 1. GET /api/events: every event as an
    //    EventSummary, soonest first.
    [HttpGet]
    public async Task<List<EventSummary>> GetAll() =>
        await db.Events
            .OrderBy(e => e.Date)
            .Select(e => new EventSummary(
                e.Id, e.Name, e.Date,
                e.Capacity - e.TicketsSold))
            .ToListAsync();

    // 2. POST /api/events/{id:int}/tickets
    //    with a NewTicket: 404 if there's no
    //    such event; 409 "Only 2 seats left."
    //    if there aren't enough. Otherwise add
    //    to TicketsSold, add a Ticket, save
    //    once, and answer 201 at GetTicket.
    [HttpPost("{id:int}/tickets")]
    public async Task<ActionResult<Ticket>> Buy(
        int id, NewTicket input)
    {
        var ev = await db.Events.FindAsync(id);
        if (ev is null)
        {
            return NotFound();
        }
        int left = ev.Capacity - ev.TicketsSold;
        if (input.Quantity > left)
        {
            return Problem(
                detail: $"Only {left} seats left.",
                statusCode: 409);
        }
        ev.TicketsSold += input.Quantity;
        var ticket = new Ticket
        {
            EventId = id,
            Buyer = input.Buyer,
            Quantity = input.Quantity,
        };
        db.Tickets.Add(ticket);
        try
        {
            await db.SaveChangesAsync();
        }
        catch (DbUpdateConcurrencyException)
        {
            return Problem(
                detail: "Those seats were just sold. Try again.",
                statusCode: 409);
        }
        return CreatedAtAction(nameof(GetTicket),
            new { id = ticket.Id }, ticket);
    }

    // 3. GET /api/tickets/{id:int}: one
    //    ticket, or 404.
    [HttpGet("/api/tickets/{id:int}")]
    public async Task<ActionResult<Ticket>> GetTicket(
        int id)
    {
        var ticket = await db.Tickets.FindAsync(id);
        if (ticket is null)
        {
            return NotFound();
        }
        return ticket;
    }

    // 4. DELETE /api/tickets/{id:int}: a
    //    refund. Give the seats back and
    //    remove the ticket, in one save.
    //    204, or 404.
    [HttpDelete("/api/tickets/{id:int}")]
    public async Task<IActionResult> Refund(int id)
    {
        var ticket = await db.Tickets.FindAsync(id);
        if (ticket is null)
        {
            return NotFound();
        }
        var ev = await db.Events.SingleAsync(
            e => e.Id == ticket.EventId);
        ev.TicketsSold -= ticket.Quantity;
        db.Tickets.Remove(ticket);
        await db.SaveChangesAsync();
        return NoContent();
    }

    // 5. (and Models.cs) If the save in 2
    //    throws DbUpdateConcurrencyException,
    //    answer 409 "Those seats were just
    //    sold. Try again."
}

